def kadane(arr):
    n = len(arr)
    current_sum = arr[0]
    best_sum = arr[0]
    current_start = 0
    best_ranges = [(0, 0)]
    i = 1
    while (i < n):
        if ((current_sum + arr[i]) < arr[i]):
            current_sum = arr[i]
            current_start = i
        else:
            current_sum = (current_sum + arr[i])
        if (current_sum > best_sum):
            best_sum = current_sum
            best_ranges = [(current_start, i)]
        elif (current_sum == best_sum):
            best_ranges.append((current_start, i))
        i = (i + 1)
    return (best_sum, best_ranges)

